`timescale 1ns/1ps
module tb;parameter integer CASE=0;reg ck=0;always #5 ck=~ck;reg rst_n=0,por_n=0;reg[142:0] pr_age=0,pr_old=0;reg ready_age=0,ready_old=0;wire[3:0] target=(CASE==1)?4'd11:4'd10;integer i;integer ticks=0,first_old=-1,first_age=-1,first_mu=-1;reg default_mismatch=0;
wire we_a,sealed_a,cf_a,df_a;wire[7:0]addr_a,fc_a;wire[63:0]data_a;wire[31:0]attn_a;wire[15:0]pv_a;wire[255:0]vp_a;
qkd_static_kv_boot_dispatch_age #(.DIECFG(1),.NRST(43),.DIECAP(1),.BOOT_AGES(1)) d_a(.ck(ck),.rst_n(rst_n),.boot_pr(pr_age),.boot_image_target(target),.boot_image_ready(ready_age),.boot_image_fault(1'b0),.boot_image_epoch(16'd1),.boot_image_digest(64'd1),.execution_active(1'b0),.sink_applied(160'd0),.local_configured(3'd0),.sink_fault(1'b0),.diecfg_sealed(sealed_a),.diecfg_fault(cf_a),.diecfg_we(we_a),.diecfg_addr(addr_a),.diecfg_data(data_a),.fault(df_a),.fault_code(fc_a));
qkd_kv_die_cfg_a #(.NRST(43),.CAP(1)) c_a(.ck(ck),.por_n(por_n),.cfg_we(we_a),.cfg_addr(addr_a),.cfg_data(data_a),.sealed(sealed_a),.fault(cf_a),.age_attn(attn_a),.age_pv(pv_a),.age_vport(vp_a));
wire we_m,sealed_m,cf_m,df_m;wire[7:0]addr_m,fc_m;wire[63:0]data_m;wire[31:0]attn_m;wire[15:0]pv_m;wire[255:0]vp_m;
qkd_static_kv_boot_dispatch_mu_age #(.DIECFG(1),.NRST(43),.DIECAP(1),.BOOT_AGES(1)) d_m(.ck(ck),.rst_n(rst_n),.boot_pr(pr_age),.boot_image_target(target),.boot_image_ready(ready_age),.boot_image_fault(1'b0),.boot_image_epoch(16'd1),.boot_image_digest(64'd1),.execution_active(1'b0),.sink_applied(160'd0),.local_configured(3'd0),.sink_fault(1'b0),.diecfg_sealed(sealed_m),.diecfg_fault(cf_m),.diecfg_we(we_m),.diecfg_addr(addr_m),.diecfg_data(data_m),.fault(df_m),.fault_code(fc_m));
qkd_kv_die_cfg_a #(.NRST(43),.CAP(1)) c_m(.ck(ck),.por_n(por_n),.cfg_we(we_m),.cfg_addr(addr_m),.cfg_data(data_m),.sealed(sealed_m),.fault(cf_m),.age_attn(attn_m),.age_pv(pv_m),.age_vport(vp_m));
wire we_off,sealed_off,cf_off,df_off;wire[7:0]addr_off,fc_off;wire[63:0]data_off;wire[31:0]attn_off;wire[15:0]pv_off;wire[255:0]vp_off;
qkd_static_kv_boot_dispatch_age #(.DIECFG(1),.NRST(43),.DIECAP(1),.BOOT_AGES(0)) d_off(.ck(ck),.rst_n(rst_n),.boot_pr(pr_old),.boot_image_target(4'd10),.boot_image_ready(ready_old),.boot_image_fault(1'b0),.boot_image_epoch(16'd1),.boot_image_digest(64'd1),.execution_active(1'b0),.sink_applied(160'd0),.local_configured(3'd0),.sink_fault(1'b0),.diecfg_sealed(sealed_off),.diecfg_fault(cf_off),.diecfg_we(we_off),.diecfg_addr(addr_off),.diecfg_data(data_off),.fault(df_off),.fault_code(fc_off));
qkd_kv_die_cfg #(.NRST(43),.CAP(1)) c_off(.ck(ck),.por_n(por_n),.cfg_we(we_off),.cfg_addr(addr_off),.cfg_data(data_off),.sealed(sealed_off),.fault(cf_off));
wire we_old,sealed_old,cf_old,df_old;wire[7:0]addr_old,fc_old;wire[63:0]data_old;wire[31:0]attn_old;wire[15:0]pv_old;wire[255:0]vp_old;
qkd_static_kv_boot_dispatch #(.DIECFG(1),.NRST(43),.DIECAP(1)) d_old(.ck(ck),.rst_n(rst_n),.boot_pr(pr_old),.boot_image_target(4'd10),.boot_image_ready(ready_old),.boot_image_fault(1'b0),.boot_image_epoch(16'd1),.boot_image_digest(64'd1),.execution_active(1'b0),.sink_applied(160'd0),.local_configured(3'd0),.sink_fault(1'b0),.diecfg_sealed(sealed_old),.diecfg_fault(cf_old),.diecfg_we(we_old),.diecfg_addr(addr_old),.diecfg_data(data_old),.fault(df_old),.fault_code(fc_old));
qkd_kv_die_cfg #(.NRST(43),.CAP(1)) c_old(.ck(ck),.por_n(por_n),.cfg_we(we_old),.cfg_addr(addr_old),.cfg_data(data_old),.sealed(sealed_old),.fault(cf_old));
task tick;begin @(posedge ck);#1;ticks=ticks+1;if(sealed_old&&first_old<0)first_old=ticks;if(sealed_a&&first_age<0)first_age=ticks;if(sealed_m&&first_mu<0)first_mu=ticks;if({we_off,addr_off,data_off,df_off,fc_off,sealed_off,cf_off}!=={we_old,addr_old,data_old,df_old,fc_old,sealed_old,cf_old})default_mismatch=1;end endtask
function automatic[63:0] age_word(input integer a);begin if(a==95)age_word=(CASE==4)?64'h1234:64'h514b564443464731;else if(a==76)age_word=(CASE==6)?64'h514b564443464731:64'h01010101;else if(a==77)age_word=(CASE==5)?9:1;else if(a==78)age_word=1;else if(a>=79)age_word=64'h0101;else age_word=0;end endfunction
task reset_all;begin @(negedge ck);rst_n=0;por_n=0;pr_age=0;pr_old=0;ready_age=0;ready_old=0;repeat(4)tick();@(negedge ck);por_n=1;rst_n=1;repeat(5)tick();end endtask
initial begin
reset_all();
for(i=0;i<((CASE==3)?97:96);i=i+1)begin @(negedge ck);pr_age=0;if(!(CASE==2&&i==5))begin pr_age[74]=1;pr_age[73:64]=10'(i);pr_age[63:0]=age_word(i);end pr_old=0;if(i<77)begin pr_old[74]=1;pr_old[73:64]=10'(i);pr_old[63:0]=(i==76)?64'h514b564443464731:0;end tick();if(!sealed_a&&(|attn_a|| |pv_a|| |vp_a))$fatal(1,"PRESEAL_AGE_LEAK");end
@(negedge ck);pr_age=0;pr_old=0;repeat(6)tick();@(negedge ck);ready_age=1;ready_old=1;repeat(3)tick();
if(default_mismatch||!sealed_off||cf_off||df_off)$fatal(1,"DEFAULT_OFF_REGRESSION");
if(CASE==0||CASE==5)begin if(df_a||df_m||cf_a||cf_m||!sealed_a||!sealed_m)$fatal(1,"AGE_BOOT_FAILED");if(attn_a!==32'h01010101||vp_a!=={16{16'h0101}}||attn_m!==attn_a||pv_m!==pv_a||vp_m!==vp_a)$fatal(1,"AGE_WIRING_ERROR");
if(CASE==5)begin if(pv_a!==16'h0109||pv_a===16'h0101)$fatal(1,"STALE_AGE_OBSERVER_MISSING");$display("EXPECTED_STALE_IMAGE_OBSERVER_MISMATCH hardware_accepts_schema_valid_stale_value");end
else begin if(first_age-first_old!=19||first_mu!=first_age)$fatal(1,"BOOT_EDGE_PRICE_MISMATCH old=%0d age=%0d mu=%0d",first_old,first_age,first_mu);$display("BOOT_DENSE_STREAM_PRICE oldseal_edge=%0d ageseal_edge=%0d MU=%0d delta=19",first_old,first_age,first_mu);if(pv_a!==16'h0101)$fatal(1,"PAIR_AGE_PACKING");@(negedge ck);rst_n=0;repeat(4)tick();if(!sealed_a||attn_a!==32'h01010101||pv_a!==16'h0101||vp_a!=={16{16'h0101}})$fatal(1,"FUNCTIONAL_RESET_LOST_CONFIG");@(negedge ck);por_n=0;repeat(4)tick();if(sealed_a||(|attn_a)||(|pv_a)||(|vp_a))$fatal(1,"POR_DID_NOT_INVALIDATE");$display("AGE96_PASS plain_and_MU_seal95 all19agewords default77PASS functionalresetRETAIN PORINVALIDATE");end end
else begin if(!(df_a||cf_a)||!(df_m||cf_m))$fatal(1,"CAUSAL_MUTANT_ESCAPED CASE=%0d",CASE);$display("EXPECTED_CAUSAL_REFUSAL CASE=%0d plain=%b/%b MU=%b/%b",CASE,df_a,cf_a,df_m,cf_m);end
$finish;end endmodule
